"add":{a:[{tr:"f. eklemek, katmak",ex:"Manufacturers sometimes add preservatives to processed food to extend its shelf life.",exTr:"Üreticiler, işlenmiş gıdanın raf ömrünü uzatmak için bazen koruyucu maddeler ekler."}],kl:[{en:"add sth to sth",tr:"bir şeye bir şey eklemek"},{en:"add to the problem",tr:"sorunu artırmak"},{en:"add up to",tr:"toplamda bir şey etmek"}]},
"career":{a:[{tr:"i. kariyer, meslek hayatı",ex:"She built a distinguished career studying the migratory patterns of Arctic seabirds.",exTr:"Arktik deniz kuşlarının göç örüntülerini inceleyerek seçkin bir kariyer inşa etti.",yz:4},{tr:"f. hızla ve kontrolsüzce gitmek",ex:"The runaway cart began to career down the steep hill before workers could stop it.",exTr:"Kontrolden çıkan araba, işçiler durduramadan dik yokuştan aşağı hızla ve kontrolsüzce gitmeye başladı.",yz:1}],kl:[{en:"pursue a career in",tr:"bir alanda kariyer peşinde koşmak"},{en:"a career change",tr:"kariyer değişikliği"},{en:"career prospects",tr:"kariyer olanakları"}]},
"convince":{a:[{tr:"f. ikna etmek",ex:"Public health campaigns aim to convince more parents to vaccinate their young children.",exTr:"Halk sağlığı kampanyaları, daha fazla ebeveyni küçük çocuklarını aşılatmaya ikna etmeyi amaçlıyor."}],kl:[{en:"convince sb of sth",tr:"birini bir şeye ikna etmek"},{en:"convince sb to do sth",tr:"birini bir şey yapmaya ikna etmek"}]},
