"huge":{a:[{tr:"s. devasa, çok büyük",ex:"Satellite images revealed a huge iceberg breaking away from the Antarctic ice shelf.",exTr:"Uydu görüntüleri, Antarktika buz sahanlığından kopan devasa bir buzdağını ortaya çıkardı."}],kl:[{en:"a huge amount of",tr:"çok büyük miktarda"},{en:"a huge impact on",tr:"çok büyük bir etki"},{en:"a huge success",tr:"büyük bir başarı"}]},
