"pattern":{a:[{tr:"i. örüntü, desen",ex:"Meteorologists have noticed an unusual pattern in seasonal rainfall across the region.",exTr:"Meteorologlar, bölgedeki mevsimsel yağışlarda alışılmadık bir örüntü fark etti.",yz:4},{tr:"f. desenlendirmek",ex:"Traditional weavers pattern each textile by hand using techniques passed down for generations.",exTr:"Geleneksel dokumacılar, nesiller boyunca aktarılan tekniklerle her kumaşı elle desenlendirir.",yz:1}],kl:[{en:"a pattern of behaviour",tr:"davranış örüntüsü"},{en:"follow a pattern",tr:"bir örüntüyü izlemek"},{en:"a similar pattern",tr:"benzer bir örüntü"}]},
"transport":{a:[{tr:"i. ulaşım, taşımacılık",ex:"Electric buses are gradually replacing diesel vehicles in urban public transport systems.",exTr:"Elektrikli otobüsler, kentsel toplu ulaşım sistemlerinde dizel araçların yerini yavaş yavaş alıyor.",yz:4},{tr:"f. taşımak, nakletmek",ex:"Refrigerated trucks transport fresh produce from farms to city markets within hours of harvest.",exTr:"Soğutmalı kamyonlar, hasattan saatler sonra taze ürünleri çiftliklerden şehir pazarlarına taşır.",yz:3}],kl:[{en:"public transport",tr:"toplu taşıma"},{en:"means of transport",tr:"ulaşım aracı"},{en:"transport goods",tr:"mal taşımak"}]},
