"inform":{a:[{tr:"f. bilgilendirmek, haberdar etmek",ex:"Doctors are required to inform patients about the possible side effects of any new medication.",exTr:"Doktorların, hastaları herhangi bir yeni ilacın olası yan etkileri hakkında bilgilendirmesi gerekir."}],kl:[{en:"inform sb of sth",tr:"birine bir şeyi bildirmek"},{en:"inform sb about sth",tr:"birine bir şey hakkında bilgi vermek"},{en:"keep sb informed",tr:"birini sürekli bilgilendirmek"}]},
"interaction":{a:[{tr:"i. etkileşim",ex:"Regular social interaction has been shown to improve mental health among elderly populations.",exTr:"Düzenli sosyal etkileşimin, yaşlı nüfuslarda ruh sağlığını iyileştirdiği gösterilmiştir."}],kl:[{en:"interaction with others",tr:"başkalarıyla etkileşim"},{en:"social interaction",tr:"sosyal etkileşim"}]},
"outcome":{a:[{tr:"i. sonuç",ex:"The long-term outcome of the treatment depends largely on how early the disease is diagnosed.",exTr:"Tedavinin uzun vadeli sonucu, büyük ölçüde hastalığın ne kadar erken teşhis edildiğine bağlıdır."}],kl:[{en:"the outcome of sth",tr:"bir şeyin sonucu"},{en:"a positive outcome",tr:"olumlu sonuç"},{en:"affect the outcome",tr:"sonuca etki etmek, sonucu değiştirmek"}]},
"publish":{a:[{tr:"f. yayımlamak, yayınlamak",ex:"The research team plans to publish their findings on renewable energy storage next spring.",exTr:"Araştırma ekibi, yenilenebilir enerji depolamayla ilgili bulgularını gelecek bahar yayımlamayı planlıyor."}],kl:[{en:"be published in a journal",tr:"bir dergide yayımlanmak"},{en:"publish a book",tr:"kitap yayımlamak"},{en:"publish research findings",tr:"araştırma bulgularını yayımlamak"}]},
"ill":{a:[{tr:"s. hasta",ex:"She had been feeling ill for several days before finally deciding to see a doctor.",exTr:"Birkaç gündür kendini hasta hissediyordu, sonunda bir doktora görünmeye karar verdi.",yz:4},{tr:"s. kötü, zararlı",ex:"Long-term exposure to air pollution can have serious ill effects on children's lung development.",exTr:"Hava kirliliğine uzun süre maruz kalmak, çocukların akciğer gelişimi üzerinde ciddi olumsuz etkilere yol açabilir.",yz:3}],kl:[{en:"fall ill",tr:"hastalanmak, rahatsızlanmak"},{en:"speak ill of sb",tr:"birinin arkasından kötü konuşmak"},{en:"ill effects",tr:"zararlı etkiler"}]},
"north":{a:[{tr:"i. kuzey",ex:"The north of the country is known for its cold winters and mountainous landscape.",exTr:"Ülkenin kuzeyi, soğuk kışları ve dağlık arazisiyle bilinir.",yz:4},{tr:"z. kuzeye",ex:"Migrating birds travel thousands of kilometers north every spring to reach their breeding grounds.",exTr:"Göçmen kuşlar, üreme alanlarına ulaşmak için her ilkbahar kuzeye doğru binlerce kilometre yol kat eder.",yz:3}],kl:[{en:"to the north of sth",tr:"bir şeyin kuzeyinde"},{en:"in the north",tr:"kuzeyde, kuzey bölgesinde"},{en:"head north",tr:"kuzeye yönelmek"}]},
"preserve":{a:[{tr:"f. korumak, muhafaza etmek",ex:"Local communities have worked for decades to preserve the ancient forest from illegal logging.",exTr:"Yerel topluluklar, kadim ormanı yasa dışı kesimden korumak için onlarca yıldır çalışıyor.",yz:4},{tr:"i. koruma alanı",ex:"The area was declared a wildlife preserve to protect endangered species from hunting.",exTr:"Bölge, nesli tükenmekte olan türleri avlanmadan korumak amacıyla bir yaban hayatı koruma alanı ilan edildi.",yz:2}],kl:[{en:"preserve the environment",tr:"çevreyi korumak"},{en:"preserve traditions",tr:"gelenekleri yaşatmak"},{en:"well preserved",tr:"iyi korunmuş"}]},
"relation":{a:[{tr:"i. ilişki, bağlantı",ex:"Historians continue to study the relation between economic instability and the rise of political extremism.",exTr:"Tarihçiler, ekonomik istikrarsızlık ile siyasi aşırıcılığın yükselişi arasındaki ilişkiyi incelemeye devam ediyor."}],kl:[{en:"in relation to sth",tr:"bir şeye ilişkin olarak"},{en:"the relation between two things",tr:"iki şey arasındaki ilişki"},{en:"public relations",tr:"halkla ilişkiler"}]},
"should/ought to have + V3":{a:[{tr:"geçmişte yapılması doğru veya beklenen fakat yapılmamış eylemi bildirmek",ex:"The agency should have consulted local residents before approving the relocation plan.",exTr:"Kurum, taşınma planını onaylamadan önce yerel halka danışmalıydı."}]},
"united":{a:[{tr:"s. birleşik, birleşmiş",ex:"Delegates from over a hundred countries remained united in calling for stronger climate policies.",exTr:"Yüzden fazla ülkeden gelen temsilciler, daha güçlü iklim politikaları çağrısında birleşik kaldı."}],kl:[{en:"united against a common enemy",tr:"ortak düşmana karşı birleşmiş"},{en:"a united front",tr:"birleşik cephe"},{en:"the United Nations",tr:"Birleşmiş Milletler"}]},
"achievement":{a:[{tr:"i. başarı",ex:"Landing a rover on Mars was considered a major achievement for the space agency.",exTr:"Mars'a bir gezici indirmek, uzay ajansı için büyük bir başarı olarak kabul edildi."}],kl:[{en:"a sense of achievement",tr:"başarma duygusu"},{en:"a great achievement",tr:"büyük bir başarı"},{en:"academic achievement",tr:"akademik başarı"}]},
"demonstrate":{a:[{tr:"f. göstermek, kanıtlamak",ex:"The experiment was designed to demonstrate how temperature affects the speed of chemical reactions.",exTr:"Deney, sıcaklığın kimyasal reaksiyonların hızını nasıl etkilediğini göstermek amacıyla tasarlandı.",yz:4},{tr:"f. gösteri yapmak",ex:"Thousands of students gathered downtown to demonstrate against the university's new tuition policy.",exTr:"Binlerce öğrenci, üniversitenin yeni harç politikasına karşı gösteri yapmak için şehir merkezinde toplandı.",yz:2}],es:"show, prove",kl:[{en:"demonstrate the importance of sth",tr:"bir şeyin önemini göstermek"},{en:"clearly demonstrate sth",tr:"bir şeyi açıkça göstermek"},{en:"demonstrate against the government",tr:"hükümete karşı gösteri yapmak"}]},
