"fight":{a:[{tr:"f. savaşmak, mücadele etmek",ex:"Public health campaigns continue to fight the spread of misinformation about vaccines.",exTr:"Halk sağlığı kampanyaları, aşılarla ilgili yanlış bilgilerin yayılmasıyla mücadeleye devam ediyor.",yz:4},{tr:"i. mücadele, kavga",ex:"A fight broke out between two rival groups outside the stadium after the match ended.",exTr:"Maç bittikten sonra stadyumun dışında iki rakip grup arasında bir kavga çıktı.",yz:3}],kl:[{en:"fight against sth",tr:"bir şeyle mücadele etmek"},{en:"fight for sth",tr:"bir şey için mücadele etmek"},{en:"put up a fight",tr:"direnç göstermek"}]},
