"serve":{a:[{tr:"f. hizmet etmek",ex:"Community clinics serve thousands of low-income families who otherwise lack access to basic healthcare.",exTr:"Toplum klinikleri, aksi takdirde temel sağlık hizmetlerine erişemeyecek binlerce düşük gelirli aileye hizmet veriyor.",yz:4},{tr:"f. sunmak, servis yapmak",ex:"The restaurant began to serve breakfast earlier than usual to accommodate early commuters.",exTr:"Restoran, erken işe gidenlere uyum sağlamak için kahvaltıyı her zamankinden daha erken sunmaya başladı.",yz:2}],kl:[{en:"serve as an example",tr:"örnek teşkil etmek"},{en:"serve a purpose",tr:"bir işe yaramak"},{en:"serve customers",tr:"müşterilere hizmet vermek"}]},
