"bacteria":{a:[{tr:"i. bakteri",ex:"Certain bacteria found in the human gut play a crucial role in digestion.",exTr:"İnsan bağırsağında bulunan belirli bakteriler, sindirimde çok önemli bir rol oynar."}],kl:[{en:"harmful bacteria",tr:"zararlı bakteriler"},{en:"kill bacteria",tr:"bakterileri öldürmek"}]},
