"objective":{a:[{tr:"s. nesnel, tarafsız",ex:"Researchers tried to remain objective while analyzing data collected from the clinical trial.",exTr:"Araştırmacılar, klinik deneyden toplanan verileri analiz ederken nesnel kalmaya çalıştı.",yz:4},{tr:"i. amaç, hedef",ex:"The company's main objective this year is to expand its operations into international markets.",exTr:"Şirketin bu yılki temel hedefi, faaliyetlerini uluslararası pazarlara genişletmektir.",yz:3}],kl:[{en:"the main objective",tr:"asıl amaç"},{en:"achieve an objective",tr:"hedefe ulaşmak"},{en:"an objective view",tr:"nesnel bakış açısı"}]},
"scale":{a:[{tr:"i. ölçek, boyut",ex:"The scale of the disaster became clear only after rescue teams reached the remote villages.",exTr:"Felaketin boyutu, ancak kurtarma ekipleri uzak köylere ulaştıktan sonra netlik kazandı.",yz:4},{tr:"f. ölçeklendirmek",ex:"Engineers had to scale the bridge design to withstand much heavier traffic loads.",exTr:"Mühendisler, çok daha ağır trafik yüklerine dayanabilmesi için köprü tasarımını ölçeklendirmek zorunda kaldı.",yz:1}],kl:[{en:"on a large scale",tr:"büyük ölçekte"},{en:"the scale of the problem",tr:"sorunun büyüklüğü"},{en:"scale up production",tr:"üretimi büyütmek"}]},
