"tree":{a:[{tr:"i. ağaç",ex:"Scientists discovered that a single mature tree can absorb around twenty kilograms of carbon dioxide each year.",exTr:"Bilim insanları, olgun tek bir ağacın her yıl yaklaşık yirmi kilogram karbondioksit emebildiğini keşfetti."}],kl:[{en:"plant a tree",tr:"ağaç dikmek"},{en:"family tree",tr:"soy ağacı"}]},
"work-in":{a:[{tr:"i. üretimi sürdürerek yapılan protesto, iş bırakmama eylemi",ex:"Employees organized a work-in to protest the factory's sudden closure while keeping production running.",exTr:"Çalışanlar, üretimi sürdürerek fabrikanın ani kapanışını protesto etmek amacıyla iş bırakmama eylemi düzenledi."}]},
